## Exercises the real package macro, argv renderer and installed generator.
## There are no fake executables, cache records or filesystem adapters. The
## JavaScript and JSON grammars are private inputs generated by this test.
## The real C compiler is part of the assertion: its source does not exist
## before this run generates it, so a prebuilt fixture cannot exercise this
## grammar/ABI/output boundary. No complete SDK or monitor is built here.
{.experimental: "callOperator".}
import std/[os, osproc, strutils, tempfiles, unittest]
import repro_project_dsl
import repro_cli_support
import repro_tool_profiles
import repro_interface_artifacts
import repro_dsl_stdlib/packages/tree_sitter as tree_sitter_module
import repro_dsl_stdlib/packages/gcc as gcc_module

proc run(action: BuildActionDef; executable, cwd: string): int =
  let argv = argvForCall(action.call,
    PathOnlyToolProfile(resolvedExecutablePath: executable))
  let child = startProcess(argv[0], workingDir = cwd,
    args = argv[1 .. ^1], options = {poParentStreams})
  result = child.waitForExit()
  child.close()

proc writeGrammarMetadata(root, name: string) =
  # ABI 15 embeds grammar metadata. Without this real upstream input the
  # generator warns and falls back to ABI 14, even when --abi 15 is present.
  # Schema: https://tree-sitter.github.io/tree-sitter/cli/init.html
  writeFile(root / "tree-sitter.json", """{
    "grammars": [{"name":"$NAME", "scope":"source.$NAME",
      "path":".", "file-types":["repro"]}],
    "metadata": {"version":"0.1.0", "license":"MIT",
      "description":"Private generation test grammar",
      "authors":[{"name":"Reprobuild"}],
      "links":{"repository":"https://github.com/metacraft-labs/reprobuild"}},
    "bindings":{"c":true}
  }""".replace("$NAME", name))

suite "tree-sitter typed parser generation":
  test "grammar, directory and ABI retain their actual command roles":
    let action = tree_sitter.generate(grammar = "grammar.js",
      outputDir = "generated", abi = 15)
    check action.call.packageName == "tree-sitter"
    check action.call.executableName == "tree-sitter"
    check action.call.subcommand == "generate"
    check action.inputs == @["grammar.js"]
    check action.outputs == @["generated"]
    check registeredBuildActions()[^1].subToolRefs == @["node"]
    var grammarInput, directoryOutput = false
    for arg in action.call.arguments:
      if arg.name == "grammar":
        grammarInput = arg.role == carInput and arg.encodedValue == "grammar.js"
      if arg.name == "outputDir":
        directoryOutput = arg.role == carOutput and arg.encodedValue == "generated"
    check grammarInput
    check directoryOutput
    check argvForCall(action.call,
      PathOnlyToolProfile(resolvedExecutablePath: "/tools/tree-sitter")) ==
      @["/tools/tree-sitter", "generate", "--output", "generated",
        "--abi", "15", "grammar.js"]
    var foundPackage = false
    for pkg in registeredPackages():
      if pkg.packageName == "tree-sitter":
        foundPackage = true
        let fingerprint = canonicalPackageInterfaceFingerprint(pkg)
        check fingerprint.len == 64
        check fingerprint != "615a1cf7519f1779f345957e62b58621bd89d931f5877010f49293815d977f11"
        echo "tree-sitter interface fingerprint: ", fingerprint
    check foundPackage

  test "required paths and typed ABI reject incomplete or malformed calls":
    static:
      doAssert not compiles(tree_sitter.generate(grammar = "grammar.js"))
      doAssert not compiles(tree_sitter.generate(outputDir = "generated"))
      doAssert not compiles(tree_sitter.generate(grammar = "grammar.js",
        outputDir = "generated", abi = "15"))
      doAssert not compiles(tree_sitter.generate(grammar = "grammar.js",
        outputDir = "generated", args = @["--no-parser"]))
    let valid = tree_sitter.generate(grammar = "grammar.js",
      outputDir = "generated", abi = 15)
    check valid.call.arguments.len == 3

  test "real JavaScript grammar generates the requested ABI and supporting files":
    let tool = findExe("tree-sitter")
    require tool.len > 0
    require findExe("node").len > 0
    let scratch = createTempDir("repro-tree-sitter-", "")
    defer: removeDir(scratch)
    let grammar = scratch / "grammar.js"
    let outputDir = scratch / "generated sources"
    writeGrammarMetadata(scratch, "repro_tiny")
    writeFile(grammar, "module.exports = grammar({name: 'repro_tiny', " &
      "rules: {source_file: $ => repeat('x')}});\n")
    let action = tree_sitter.generate(grammar = grammar,
      outputDir = outputDir, abi = 15)
    require action.run(tool, scratch) == 0
    check fileExists(outputDir / "parser.c")
    check "#define LANGUAGE_VERSION 15" in readFile(outputDir / "parser.c")
    check fileExists(outputDir / "tree_sitter" / "parser.h")
    check fileExists(outputDir / "grammar.json")
    check fileExists(outputDir / "node-types.json")

    # Directory-child inference is not assumed. The canonical typed `after`
    # parameter records the dependency on this real generation action.
    let compiler = findExe("gcc")
    require compiler.len > 0
    let objectPath = scratch / "parser.o"
    let consumer = gcc(source = outputDir / "parser.c", output = objectPath,
      includeDirs = @[outputDir], compileOnly = true, after = @[action])
    check consumer.deps == @[action.id]
    let decoded = decodeBuildActionPayload(encodeBuildActionPayload(consumer))
    check decoded.deps == consumer.deps
    require consumer.run(compiler, scratch) == 0
    check fileExists(objectPath)

    let refusedOutput = scratch / "invalid-abi"
    let refused = tree_sitter.generate(grammar = grammar,
      outputDir = refusedOutput, abi = 999)
    check refused.run(tool, scratch) != 0
    check not fileExists(refusedOutput / "parser.c")

  test "real JSON grammar generation and missing grammar refusal":
    let tool = findExe("tree-sitter")
    require tool.len > 0
    let scratch = createTempDir("repro-tree-sitter-json-", "")
    defer: removeDir(scratch)
    let grammar = scratch / "grammar.json"
    writeGrammarMetadata(scratch, "repro_json")
    writeFile(grammar, """{"name":"repro_json","rules":{"source_file":{"type":"STRING","value":"x"}}}""")
    # Implicit target names are project-scoped even when this whole program
    # runs all cases in one process; keep this output name distinct.
    let outputDir = scratch / "json-generated"
    let action = tree_sitter.generate(grammar = grammar,
      outputDir = outputDir, abi = 15)
    require action.run(tool, scratch) == 0
    check "#define LANGUAGE_VERSION 15" in readFile(outputDir / "parser.c")
    let missing = tree_sitter.generate(grammar = scratch / "missing.json",
      outputDir = scratch / "missing-output", abi = 15)
    check missing.run(tool, scratch) != 0
    check not fileExists(scratch / "missing-output" / "parser.c")
